static ut64 buf_get_size(RBuffer *b) { /* <=== buf_get_size */ 
	r_return_val_if_fail (b && b->methods, UT64_MAX);
	return b->methods->get_size? b->methods->get_size (b): UT64_MAX;
}

R_API void r_list_init(RList *list) { /* <=== r_list_init */ 
	list->head = NULL;
	list->tail = NULL;
	list->free = NULL;
	list->length = 0;
	list->sorted = false;
}

R_API RList *r_list_newf(RListFree f) { /* <=== r_list_newf */ 
	RList *l = r_list_new ();
	if (l) {
		l->free = f;
	}
	return l;
}

R_API RList *r_list_new(void) { /* <=== r_list_new */ 
	RList *list = R_NEW0 (RList);
	if (!list) {
		return NULL;
	}
	r_list_init (list);
	return list;
}

RList *r_bin_ne_get_segments(r_bin_ne_obj_t *bin) { /* <=== r_bin_ne_get_segments */ 
	int i;
	if (!bin) {
		return NULL;
	}
	RList *segments = r_list_newf (free);
	for (i = 0; i < bin->ne_header->SegCount; i++) {
		RBinSection *bs = R_NEW0 (RBinSection);
		if (!bs) {
			return segments;
		}
		NE_image_segment_entry *se = &bin->segment_entries[i];
		bs->size = se->length;
		bs->vsize = se->minAllocSz ? se->minAllocSz : 64000;
		bs->bits = R_SYS_BITS_16;
		bs->is_data = se->flags & IS_DATA;
		bs->perm = __translate_perms (se->flags);
		bs->paddr = (ut64)se->offset * bin->alignment;
		bs->name = r_str_newf ("%s.%" PFMT64d, se->flags & IS_MOVEABLE ? "MOVEABLE" : "FIXED", bs->paddr);
		bs->is_segment = true;
		r_list_append (segments, bs);
	}
	bin->segments = segments;
	return segments;
}

R_API void *r_list_get_n(const RList *list, int n) { /* <=== r_list_get_n */ 
	RListIter *it;
	int i;

	r_return_val_if_fail (list, NULL);

	for (it = list->head, i = 0; it && it->data; it = it->n, i++) {
		if (i == n) {
			return it->data;
		}
	}
	return NULL;
}

static int __translate_perms(int flags) { /* <=== __translate_perms */ 
	int perms = 0;
	if (flags & IS_RX) {
		if (flags & IS_DATA) {
			perms = R_PERM_R;
		} else {
			perms = R_PERM_X;
		}
	}
	if (!perms) {
		perms = R_PERM_RWX;
	}
	return perms;
}

R_API void r_list_purge(RList *list) { /* <=== r_list_purge */ 
	if (!list) {
		return;
	}
	RListIter *it = list->head;
	while (it) {
		RListIter *next = it->n;
		r_list_delete (list, it);
		it = next;
	}
	list->length = 0;
	list->head = list->tail = NULL;
}

R_API void r_list_free(RList *list) { /* <=== r_list_free */ 
	if (list) {
		r_list_purge (list);
		free (list);
	}
}

R_API void r_list_delete(RList *list, RListIter *iter) { /* <=== r_list_delete */ 
	r_return_if_fail (list && iter);
	r_list_split_iter (list, iter);
	if (list->free && iter->data) {
		list->free (iter->data);
	}
	iter->data = NULL;
	free (iter);
}

R_API RListIter *r_list_item_new(void *data) { /* <=== r_list_item_new */ 
	RListIter *item = R_NEW0 (RListIter);
	if (item) {
		item->data = data;
	}
	return item;
}

R_API ut64 r_buf_size(RBuffer *b) { /* <=== r_buf_size */ 
	r_return_val_if_fail (b, 0);
	return buf_get_size (b);
}

R_API RListIter *r_list_append(RList *list, void *data) { /* <=== r_list_append */ 
	r_return_val_if_fail (list, NULL);

	RListIter *item = r_list_item_new (data);
	if (!item) {
		return NULL;
	}
	if (list->tail) {
		list->tail->n = item;
	}
	item->p = list->tail;
	list->tail = item;
	if (!list->head) {
		list->head = item;
	}
	list->length++;
	list->sorted = false;
	return item;
}

